// Line 10-90: Unit tests for isLocalURL()
test("isLocalURL detects localhost", () => {
  expect(Provider.isLocalURL("http://localhost:11434")).toBe(true)
  expect(Provider.isLocalURL("http://localhost:8080/v1")).toBe(true)
})

test("isLocalURL detects 127.0.0.1", () => {
  expect(Provider.isLocalURL("http://127.0.0.1:8080")).toBe(true)
})

test("isLocalURL detects private IPv4 ranges", () => {
  expect(Provider.isLocalURL("http://10.0.0.1:8080")).toBe(true)
  expect(Provider.isLocalURL("http://172.16.0.1:8080")).toBe(true)
  expect(Provider.isLocalURL("http://192.168.0.1:8080")).toBe(true)
})

test("isLocalURL returns false for public URLs", () => {
  expect(Provider.isLocalURL("https://api.openai.com")).toBe(false)
  expect(Provider.isLocalURL("http://8.8.8.8:8080")).toBe(false)
})

// Line 18-178: Integration tests
test("chunkTimeout auto-disabled for localhost URLs", async () => {
  // Config with localhost URL
  const config = {
    provider: {
      ollama: {
        id: "llama3",
        npm: "@ai-sdk/openai-compatible",
        baseURL: "http://localhost:11434/v1",
      },
    },
  }
  // Verify chunkTimeout is 0
  expect(providers["ollama"].options.chunkTimeout).toBe(0)
})

test("chunkTimeout uses default for public URLs", async () => {
  // Remote URL should get 900000ms (15 min)
  expect(providers["remote"].options.chunkTimeout).toBe(900000)
})
